const result = await tools.image_gen__imagegen({
  prompt: `Create ONE standalone card-theme illustration. Subject: a key ring holding three distinct keys fanned apart beside an open padlock. Must keep: exactly three separate keys on one key ring; the padlock beside the keys is open.
